from pathlib import Path
import sqlite3


SYSTEM = "court_case_management"
CASE_ID = "CASE-GZ-2024-1847"
TARGET_SNAPSHOT_ID = "SNAP-GZ20241847-READY"


def _db_path(ws):
    path = Path(ws).resolve().parent / "system" / SYSTEM / "state.db"
    if not path.exists():
        raise FileNotFoundError(f"Missing database: {path}")
    return path


def _rows(path, sql, params=()):
    connection = sqlite3.connect(path)
    connection.row_factory = sqlite3.Row
    try:
        return [dict(row) for row in connection.execute(sql, params).fetchall()]
    finally:
        connection.close()


def check_snapshot_recomputed_counts(ws):
    rows = _rows(
        _db_path(ws),
        "SELECT snapshot_id, material_count, event_count FROM case_archive_snapshot WHERE snapshot_id = ?",
        (TARGET_SNAPSHOT_ID,),
    )
    if len(rows) != 1:
        return {"score": 0, "detail": "The target archive-ready snapshot is missing or duplicated."}
    row = rows[0]
    if row["material_count"] == 71 and row["event_count"] == 7:
        return {"score": 1, "detail": "Target snapshot stores 71 materials and 7 conventional events."}
    return {"score": 0, "detail": f"Unexpected recomputed counts: {row}"}


def check_snapshot_ready_state(ws):
    rows = _rows(
        _db_path(ws),
        """SELECT snapshot_status, confirmed_by, catalog_status, identity_check_status
           FROM case_archive_snapshot WHERE snapshot_id = ?""",
        (TARGET_SNAPSHOT_ID,),
    )
    if len(rows) != 1:
        return {"score": 0, "detail": "The target archive-ready snapshot is missing or duplicated."}
    row = rows[0]
    expected = {
        "snapshot_status": "ready",
        "confirmed_by": "STAFF-CLERK-LI-MIN",
        "catalog_status": "completed",
        "identity_check_status": "passed",
    }
    if row == expected:
        return {"score": 1, "detail": "Target snapshot is ready with completed catalog and passed identity verification."}
    return {"score": 0, "detail": f"Unexpected target snapshot state: {row}"}


def check_source_records_unchanged(ws):
    current = _db_path(ws)
    baseline = current.with_name("state.db.pinned_backup")
    if not baseline.exists():
        return {"score": 0, "detail": "Pinned baseline database is missing."}
    checks = [
        ("case_master", "SELECT * FROM case_master WHERE case_id = ? ORDER BY case_id"),
        ("case_party", "SELECT * FROM case_party WHERE case_id = ? ORDER BY sequence_no, party_id"),
        ("case_procedure_event", "SELECT * FROM case_procedure_event WHERE case_id = ? ORDER BY event_id"),
    ]
    for label, sql in checks:
        if _rows(current, sql, (CASE_ID,)) != _rows(baseline, sql, (CASE_ID,)):
            return {"score": 0, "detail": f"Protected source records changed in {label}."}
    return {"score": 1, "detail": "Case master, parties, and procedure events match the pinned baseline."}


def check_historical_snapshots_unchanged(ws):
    current = _db_path(ws)
    baseline = current.with_name("state.db.pinned_backup")
    if not baseline.exists():
        return {"score": 0, "detail": "Pinned baseline database is missing."}
    sql = """SELECT * FROM case_archive_snapshot
             WHERE case_id = ? AND snapshot_id <> ? ORDER BY snapshot_id"""
    params = (CASE_ID, TARGET_SNAPSHOT_ID)
    if _rows(current, sql, params) != _rows(baseline, sql, params):
        return {"score": 0, "detail": "The target case's historical archive snapshot changed."}
    return {"score": 1, "detail": "The target case's historical archive snapshot is unchanged."}
